import ListingListener from "./makaira-filter/filter/listing.plugin";

// Flag to prevent double registration
let isListingListenerRegistered = false;

/**
 * Safely check if a plugin is already registered
 * @param {string} pluginName - Name of the plugin to check
 * @returns {boolean} - True if plugin exists, false otherwise
 */
function isPluginRegistered(pluginName) {
  if (!window.PluginManager) {
    return false;
  }

  try {
    // Method 1: Try to get the plugin directly
    const plugin = window.PluginManager.getPlugin(pluginName);
    return !!plugin;
  } catch (error) {
    // Method 2: Check if PluginManager has a registry or plugins property
    if (window.PluginManager.plugins && window.PluginManager.plugins[pluginName]) {
      return true;
    }

    // Method 3: Check if there are any elements with the plugin's data attribute
    const elements = document.querySelectorAll(`[data-${pluginName.toLowerCase()}]`);
    if (elements.length > 0) {
      // Check if any of these elements have the plugin instance
      for (const element of elements) {
        try {
          const instance = window.PluginManager.getPluginInstanceFromElement(element, pluginName);
          if (instance) {
            return true;
          }
        } catch (e) {
          // Continue checking other elements
        }
      }
    }

    return false;
  }
}

// Store the original methods to prevent early initialization and async loading issues
let originalInitializePlugins = null;
let pluginsInitialized = false;

// Dynamic import map to cache preloaded modules
const moduleCache = new Map();
const moduleImportMap = {
  'makaira.listing.plugin': () => import('./makaira-filter/makaira.listing.plugin'),
  // Add more modules here as needed
  // 'other.module': () => import('./path/to/other/module'),
};

// Utility function to get a module from cache
const getModuleFromCache = (moduleKey) => {
  return moduleCache.get(moduleKey);
};

// Make modules globally accessible for Shopware's async loading
window.MakairaModules = {
  get: getModuleFromCache,
  has: (key) => moduleCache.has(key),
  list: () => Array.from(moduleCache.keys()),
  cache: moduleCache
};

document.addEventListener("DOMContentLoaded", () => {
  if (window.PluginManager && !isListingListenerRegistered) {
    // Store the original method to prevent automatic initialization
    if (!originalInitializePlugins) {
      originalInitializePlugins = window.PluginManager.initializePlugins;

      window.PluginManager.initializePlugins = () => {
        // Do nothing - we'll call the original method when ready
        console.log("Preventing early plugin initialization...");
      };
      
      // Override async plugin fetching to use our cached modules
      if (window.PluginManager._fetchAsyncPlugins) {
        const originalFetchAsync = window.PluginManager._fetchAsyncPlugins;
        window.PluginManager._fetchAsyncPlugins = async function(...args) {
          console.log("Intercepting async plugin fetch, checking cache first...");
          
          // Check if we have the requested module in cache
          const requestedModule = args[0]; // Usually the first argument contains module info
          if (requestedModule && typeof requestedModule === 'string') {
            const cachedModule = getModuleFromCache(requestedModule);
            if (cachedModule) {
              console.log(`✅ Found module "${requestedModule}" in cache, returning immediately`);
              return cachedModule;
            }
          }
          
          // Fall back to original method if not in cache
          console.log("Module not in cache, falling back to original async fetch...");
          return originalFetchAsync.apply(this, args);
        };
      }
    }

    // Only register if not already registered
    if (isPluginRegistered("ListingListener")) {
      isListingListenerRegistered = true;
      return;
    }

    // Register the ListingListener plugin
    try {
      window.PluginManager.register(
        "ListingListener",
        ListingListener,
        "[data-listing-listener]"
      );
      isListingListenerRegistered = true;
    } catch (error) {
      console.error("Failed to register ListingListener plugin:", error);
    }

    // Preload all modules in the import map
    const preloadAllModules = async () => {
      console.log("Preloading all modules from import map...");
      const promises = Object.entries(moduleImportMap).map(async ([key, importFn]) => {
        try {
          const module = await importFn();
          moduleCache.set(key, module);
          console.log(`✅ Module "${key}" preloaded successfully`);
          return { key, success: true };
        } catch (error) {
          console.error(`❌ Failed to preload module "${key}":`, error);
          return { key, success: false, error };
        }
      });
      
      const results = await Promise.allSettled(promises);
      const successful = results.filter(r => r.status === 'fulfilled' && r.value.success).length;
      const failed = results.length - successful;
      console.log(`📦 Module preloading complete: ${successful} successful, ${failed} failed`);
    };

    // Register MakairaListing as a separate plugin to avoid override issues
    const initializeWithMakairaListing = async () => {
      try {
        // First preload all modules
        await preloadAllModules();
        
        // Get the preloaded MakairaListing module from cache
        const MakairaListingModule = moduleCache.get('makaira.listing.plugin');
        if (!MakairaListingModule) {
          throw new Error('MakairaListing module not found in cache after preloading');
        }
        
        const MakairaListing = MakairaListingModule.default;

        // Register MakairaListing as a separate plugin instead of overriding
        if (!isPluginRegistered("MakairaListing")) {
          window.PluginManager.register(
            "MakairaListing",
            MakairaListing,
            "[data-listing]"
          );
        } else {

        }
      } catch (error) {
        console.error("Failed to register MakairaListing plugin:", error);
      }

      // Now initialize plugins
      if (!pluginsInitialized && originalInitializePlugins) {
        try {
          // Restore the original method and call it
          window.PluginManager.initializePlugins = originalInitializePlugins;
          window.PluginManager.initializePlugins();
          pluginsInitialized = true;
        } catch (error) {
          console.error("Failed to initialize plugins:", error);
        }
      }
    };

    // Start the async initialization process
    setTimeout(initializeWithMakairaListing, 50);
  }
});
